ext('c12_math_ch3',[
C("🔢","आव्यूह के गुणन का नियम",["पहले की स्तंभ संख्या बराबर दूसरे की पंक्ति संख्या","पंक्ति और स्तंभ के गुणनफल का योग","क्रम महत्त्वपूर्ण","AB और BA बराबर नहीं होते"],"दो आव्यूहों का गुणन तभी संभव है जब पहले आव्यूह के स्तंभों की संख्या दूसरे आव्यूह की पंक्तियों की संख्या के बराबर हो। परिणामी आव्यूह का हर अवयव पहली की एक पंक्ति और दूसरी के एक स्तंभ के संगत अवयवों के गुणनफल का योग होता है। गुणन में क्रम बदलने पर परिणाम बदल जाता है।"),
C("🔁","परिवर्त आव्यूह",["पंक्ति को स्तंभ बनाना","आव्यूह का तिरछा उलटना","A′ का परिवर्त A","गुणन का परिवर्त उलटे क्रम में"],"किसी आव्यूह की पंक्तियों को स्तंभ और स्तंभों को पंक्तियाँ बना देने पर उसका परिवर्त आव्यूह बनता है। परिवर्त का परिवर्त वापस मूल आव्यूह होता है। दो आव्यूहों के गुणनफल का परिवर्त उनके परिवर्तों के उलटे क्रम में गुणनफल के बराबर होता है। यह गुण कई सवालों में काम आता है।"),
C("⚖️","सममित और विषम सममित",["सममित: A′ = A","विषम सममित: A′ = −A","विषम सममित में विकर्ण शून्य","हर वर्ग आव्यूह दोनों का योग"],"जिस आव्यूह का परिवर्त उसके बराबर हो, वह सममित कहलाता है। जिसका परिवर्त उसके ऋणात्मक के बराबर हो, वह विषम सममित है। विषम सममित आव्यूह के सभी विकर्ण अवयव शून्य होते हैं। हर वर्ग आव्यूह को एक सममित और एक विषम सममित आव्यूह के योग के रूप में लिखा जा सकता है।"),
C("🧮","प्रारंभिक संक्रियाएँ",["दो पंक्तियाँ आपस में बदलना","किसी पंक्ति को अशून्य संख्या से गुणा","एक पंक्ति में दूसरी का गुणज जोड़ना","प्रतिलोम निकालने की विधि"],"आव्यूह पर तीन प्रकार की प्रारंभिक संक्रियाएँ की जाती हैं। दो पंक्तियों की अदला-बदली, किसी पंक्ति को शून्येतर संख्या से गुणा करना, और एक पंक्ति में दूसरी पंक्ति का गुणज जोड़ना। इनसे आव्यूह को सरल रूप में लाया जाता है, और इसी विधि से प्रतिलोम आव्यूह भी निकाला जा सकता है।"),
C("🔙","प्रतिलोम आव्यूह का अस्तित्व",["वर्ग आव्यूह होना चाहिए","सारणिक शून्येतर","AB = BA = I","प्रतिलोम अद्वितीय होता है"],"किसी आव्यूह का प्रतिलोम तब होता है जब वह वर्ग आव्यूह हो और उसका सारणिक शून्य न हो। प्रतिलोम वह आव्यूह है जिससे गुणा करने पर तत्समक आव्यूह मिलता है। एक आव्यूह का प्रतिलोम अगर होता है तो केवल एक ही होता है। जिनका सारणिक शून्य हो, उन्हें अव्युत्क्रमणीय कहते हैं।"),
],5)
ext('c12_math_ch4',[
C("🔢","सारणिक के गुण",["पंक्ति और स्तंभ बदलने पर मान वही","दो पंक्ति बदलें तो चिह्न बदलता","दो पंक्तियाँ समान हों तो शून्य","किसी पंक्ति को गुणा करने से मान गुणा"],"सारणिक के कई उपयोगी गुण हैं। उसकी पंक्तियों और स्तंभों की अदला-बदली करने पर मान नहीं बदलता। दो पंक्तियाँ आपस में बदलने पर चिह्न उलट जाता है। दो पंक्तियाँ समान हों तो सारणिक का मान शून्य होता है। किसी पंक्ति को संख्या से गुणा करने पर पूरा सारणिक उसी संख्या से गुणा हो जाता है।"),
C("📐","त्रिभुज के क्षेत्रफल में सारणिक",["तीन शीर्षों के निर्देशांक","3×3 सारणिक बनाइए","आधे का गुणा","क्षेत्रफल धनात्मक लें"],"अगर तीन बिंदुओं के निर्देशांक पता हों, तो उनसे बने त्रिभुज का क्षेत्रफल सारणिक से निकाला जा सकता है। निर्देशांकों से तीन गुणा तीन का सारणिक बनाइए और उसके मान का आधा लीजिए। क्षेत्रफल हमेशा धनात्मक होता है, इसलिए सारणिक का मान ऋणात्मक आए तो उसका निरपेक्ष मान लीजिए। अगर तीनों बिंदु एक रेखा पर हों तो क्षेत्रफल शून्य होगा।"),
C("🔍","उपसारणिक और सहखंड",["एक पंक्ति और स्तंभ हटाने से बना","चिह्न का नियम","सहखंड = उपसारणिक × चिह्न","विस्तार में उपयोगी"],"किसी अवयव की पंक्ति और स्तंभ हटाने पर जो सारणिक बचता है, वह उस अवयव का उपसारणिक है। उसे उचित चिह्न के साथ गुणा करने पर सहखंड मिलता है। चिह्न का नियम यह है कि पंक्ति और स्तंभ संख्या का योग सम हो तो धन, और विषम हो तो ऋण। सारणिक का विस्तार इन्हीं सहखंडों से किया जाता है।"),
C("🧮","क्रैमर का नियम",["तीन चर वाले समीकरण","मुख्य सारणिक अशून्य","हर चर के लिए अलग सारणिक","चर = उसका सारणिक भाग मुख्य"],"रैखिक समीकरण निकाय को क्रैमर के नियम से भी हल किया जाता है। पहले मुख्य सारणिक निकालिए, जो शून्य नहीं होना चाहिए। फिर हर चर के लिए एक अलग सारणिक बनाइए, जिसमें उस चर के स्तंभ की जगह अचर पद रखे जाते हैं। हर चर का मान उसके सारणिक को मुख्य सारणिक से भाग देने पर मिलता है।"),
C("🚫","संगत और असंगत निकाय",["सारणिक अशून्य: अद्वितीय हल","सारणिक शून्य और कुछ शर्तें","संगत: कम से कम एक हल","असंगत: कोई हल नहीं"],"जब रैखिक समीकरण निकाय के गुणांक आव्यूह का सारणिक शून्येतर हो, तो निकाय का एक अद्वितीय हल मिलता है। अगर सारणिक शून्य हो, तो या तो अनंत हल होंगे या कोई हल नहीं होगा। जिस निकाय का कम से कम एक हल हो उसे संगत कहते हैं, और जिसका कोई हल न हो उसे असंगत।"),
],5)
ext('c12_math_ch5',[
C("🔗","सांतत्य की जाँच",["बाएँ और दाएँ सीमा","फलन का मान","तीनों बराबर हों","तभी सतत"],"किसी बिंदु पर फलन सतत है या नहीं, यह जाँचने के लिए तीन चीज़ें देखी जाती हैं। उस बिंदु पर बाएँ से सीमा, दाएँ से सीमा और फलन का मान। अगर तीनों बराबर हों, तो फलन उस बिंदु पर सतत है। अगर इनमें कोई भी अलग हो, तो फलन वहाँ असतत होता है।"),
C("🔄","श्रृंखला नियम",["फलन के भीतर फलन","बाहरी का अवकलज × भीतरी का अवकलज","संयुक्त फलन के लिए","अवकलन की सबसे ज़रूरी विधि"],"जब कोई फलन किसी दूसरे फलन के भीतर हो, तो उसे अवकलित करने के लिए श्रृंखला नियम लगाते हैं। इसमें बाहरी फलन का अवकलज लेकर उसे भीतरी फलन के अवकलज से गुणा करते हैं। जैसे साइन के भीतर x वर्ग हो, तो पहले कोज्या x वर्ग लिखिए और फिर उसे दो x से गुणा कीजिए।"),
C("📈","लघुगणकीय अवकलन",["घात में चर","दोनों तरफ़ लघुगणक","लघुगणक के गुण से सरल","फिर अवकलन"],"जब किसी फलन में चर ही घात में हो, जैसे x की घात x, तब लघुगणकीय अवकलन काम आता है। पहले दोनों तरफ़ लघुगणक लिया जाता है। लघुगणक के गुणों से घात नीचे आ जाती है और व्यंजक सरल हो जाता है। उसके बाद अवकलन करते हैं और आख़िर में मूल फलन से गुणा कर देते हैं।"),
C("🧩","अप्रत्यक्ष और प्राचलिक अवकलन",["जब y सीधे x में न हो","दोनों तरफ़ x के सापेक्ष अवकलन","प्राचलिक में dy/dt भाग dx/dt","श्रृंखला नियम का ही उपयोग"],"जब y और x का संबंध मिश्रित रूप में दिया हो, तो दोनों पक्षों को x के सापेक्ष अवकलित करते हैं और y का अवकलज अलग निकालते हैं। जब दोनों किसी तीसरे चर t के रूप में हों, तो y के t-अवकलज को x के t-अवकलज से भाग देते हैं। दोनों विधियों में श्रृंखला नियम का ही उपयोग होता है।"),
C("📊","मध्यमान प्रमेय",["सतत और अवकलनीय फलन","बंद अंतराल पर","एक बिंदु जहाँ ढाल औसत ढाल के बराबर","रोले प्रमेय विशेष स्थिति"],"मध्यमान प्रमेय कहता है कि अगर कोई फलन किसी बंद अंतराल पर सतत और खुले अंतराल पर अवकलनीय हो, तो उस अंतराल में कम से कम एक बिंदु ऐसा होता है जहाँ स्पर्श रेखा का ढाल औसत ढाल के बराबर होता है। रोले का प्रमेय इसी की एक विशेष स्थिति है, जब दोनों सिरों पर मान समान हों।"),
],5)
ext('c12_math_ch6',[
C("📈","वर्धमान और ह्रासमान फलन",["अवकलज धनात्मक: वर्धमान","अवकलज ऋणात्मक: ह्रासमान","अंतराल पर जाँच","चिह्न-सारणी से हल"],"अगर किसी अंतराल में फलन का अवकलज धनात्मक हो, तो फलन उस अंतराल में वर्धमान होता है। अगर अवकलज ऋणात्मक हो, तो फलन ह्रासमान होता है। इसे जाँचने के लिए पहले अवकलज निकालिए और उसका चिह्न अलग-अलग अंतरालों में देखिए। चिह्न-सारणी बनाने से यह काम आसान हो जाता है।"),
C("📍","स्पर्श रेखा का समीकरण",["बिंदु पर अवकलज = ढाल","बिंदु और ढाल से समीकरण","अभिलंब का ढाल उलटा-ऋणात्मक","दोनों रेखाएँ बिंदु पर लंब"],"किसी वक्र के एक बिंदु पर स्पर्श रेखा का ढाल उस बिंदु पर अवकलज के बराबर होता है। बिंदु और ढाल पता हो तो रेखा का समीकरण लिखा जा सकता है। अभिलंब स्पर्श रेखा के लंबवत होता है, इसलिए उसका ढाल स्पर्श रेखा के ढाल का उलटा और ऋणात्मक होता है।"),
C("⛰️","उच्चिष्ठ और निम्निष्ठ बिंदु",["अवकलज शून्य: क्रांतिक बिंदु","चिह्न धन से ऋण: उच्चिष्ठ","चिह्न ऋण से धन: निम्निष्ठ","द्वितीय अवकलज परीक्षण"],"जहाँ फलन का अवकलज शून्य होता है, उसे क्रांतिक बिंदु कहते हैं। अगर वहाँ अवकलज का चिह्न धनात्मक से ऋणात्मक हो जाए, तो वह उच्चिष्ठ बिंदु है। अगर ऋणात्मक से धनात्मक हो जाए, तो वह निम्निष्ठ बिंदु है। द्वितीय अवकलज ऋणात्मक हो तो उच्चिष्ठ, और धनात्मक हो तो निम्निष्ठ होता है।"),
C("📦","एक अनुकूलतम उदाहरण",["तार से अधिकतम क्षेत्रफल","आयताकार खेत","सूत्र बनाकर अवकलन","आयत वर्ग बनता है"],"मान लीजिए आपके पास सौ मीटर तार है और उससे एक आयताकार खेत घेरना है जिसका क्षेत्रफल सबसे ज़्यादा हो। लंबाई और चौड़ाई का संबंध लिखकर क्षेत्रफल एक चर के रूप में लिखिए। उसका अवकलज शून्य करने पर पता चलता है कि लंबाई और चौड़ाई बराबर होने पर क्षेत्रफल सबसे ज़्यादा होता है, यानी खेत वर्गाकार होना चाहिए।"),
C("📏","सन्निकटन",["छोटे परिवर्तन के लिए","dy ≈ f′(x) dx","वर्गमूल का आसान मान","त्रुटि का अनुमान"],"जब चर में बहुत छोटा बदलाव हो, तो फलन के बदलाव का मान अवकलज और परिवर्तन के गुणनफल से लगभग निकाला जा सकता है। इसकी मदद से किसी संख्या के वर्गमूल का लगभग मान आसानी से निकल आता है। इसी तरह मापन में हुई छोटी त्रुटि का अंतिम परिणाम पर असर भी इस विधि से पता लगाया जाता है।"),
],5)
ext('c12_math_ch7',[
C("🔁","समाकलन अवकलन का उलटा",["अवकलज दिया हो तो मूल फलन","स्थिरांक C जोड़ना ज़रूरी","अनिश्चित समाकल","परिणाम फलनों का परिवार"],"समाकलन अवकलन की उलटी प्रक्रिया है। जब किसी फलन का अवकलज दिया हो, तब मूल फलन ढूँढ़ना समाकलन कहलाता है। इसमें हमेशा एक स्थिरांक जोड़ना पड़ता है, क्योंकि स्थिरांक का अवकलज शून्य होता है। इसलिए उत्तर कोई एक फलन नहीं बल्कि फलनों का एक पूरा परिवार होता है।"),
C("🧮","प्रतिस्थापन विधि",["जटिल भाग को नया चर मानें","dx को नए चर में बदलें","समाकल सरल बनता है","अंत में वापस मूल चर"],"जब समाकल जटिल हो, तो उसके किसी भाग को नया चर मान लिया जाता है, जैसे u। फिर dx को u और du के रूप में बदला जाता है। इससे समाकल सरल मानक रूप में आ जाता है। हल करने के बाद u की जगह वापस मूल चर रख दिया जाता है। यह सबसे अधिक काम आने वाली विधि है।"),
C("➗","आंशिक भिन्न विधि",["भिन्न को सरल भिन्नों में तोड़ना","हर का गुणनखंडन","अज्ञात गुणांक निकालना","हर भिन्न का अलग समाकल"],"जब समाकलन में हर वाली भिन्न हो, तो उसे आंशिक भिन्नों में तोड़ते हैं। इसके लिए पहले हर का गुणनखंड करते हैं। फिर हर गुणनखंड के लिए अज्ञात गुणांक मानकर उन्हें निकाला जाता है। इसके बाद हर सरल भिन्न का अलग-अलग समाकल लेना आसान हो जाता है, और उन्हें जोड़कर पूरा उत्तर मिलता है।"),
C("🧩","खंडशः समाकलन",["दो फलनों का गुणनफल","पहला और दूसरा फलन चुनना","सूत्र: u v − समाकल v du","ILATE का क्रम"],"जब दो फलनों का गुणनफल समाकलित करना हो, तो खंडशः समाकलन का सूत्र लगाते हैं। पहला फलन चुनने के लिए एक क्रम याद रखा जाता है, पहले व्युत्क्रम त्रिकोणमितीय, फिर लघुगणकीय, बीजीय, त्रिकोणमितीय और अंत में चरघातांकी। इस क्रम में जो पहले आए, उसे पहला फलन मानते हैं।"),
C("📏","निश्चित समाकल के गुण",["सीमाएँ बदलने पर चिह्न बदलता","अंतराल को तोड़ा जा सकता है","सम फलन के लिए दोगुना","विषम फलन के लिए शून्य"],"निश्चित समाकल में ऊपरी और निचली सीमा होती हैं। सीमाओं की अदला-बदली करने पर चिह्न बदल जाता है। अंतराल को दो भागों में तोड़कर अलग-अलग समाकल जोड़ सकते हैं। अगर फलन सम हो और सीमाएँ माइनस a से a हों, तो परिणाम शून्य से a तक के समाकल का दोगुना होता है। विषम फलन के लिए यह शून्य होता है।"),
],5)
